        foreach (int num in arr2)
        {
            if (frequencyMap.ContainsKey(num))
            {
                commonCount++;
                if (commonCount == 3)
                {
                    return num; // Return the third common element
                }
            }
        }

        // If there is no third common element, return -1
        return -1;
    }
}
